import type { Metadata } from 'next'
import { site } from '@/data/site'

/**
 * Next.js replaces (does not merge) a parent's `openGraph` object when a page sets its own,
 * so every page builds its Open Graph tags through this helper to keep siteName/locale/type.
 * The share image is generated by app/opengraph-image.tsx.
 */
export function pageMeta({
  title,
  description,
  path,
}: {
  title: string
  description: string
  path: string
}): Metadata {
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: 'website',
      locale: 'en_US',
      siteName: site.name,
      url: path,
      title,
      description,
      images: [{ url: '/opengraph-image', width: 1200, height: 630, alt: `${site.name}: custom websites for Connecticut small businesses` }],
    },
  }
}
